def truncate(text, limit):
    """Shorten text to at most `limit` characters, cutting at the last full word that fits and adding "..."."""
    if len(text) <= limit:
        return text
    # Need room for "..." (3 chars). Find the last whitespace position k that
    # lets text[:k] + "..." fit; text[:k] then ends on a whole word.
    for k in range(min(limit - 3, len(text) - 1), -1, -1):
        if text[k].isspace():
            head = text[:k].rstrip()
            if head:
                return head + "..."
            break
    return "..."

